# UIMRS production-style local launcher (public release).
# Requires the local secret generated by setup_public_environment.cmd and sets
# UIMRS_ENV=production so the strict secret-key rules are enforced.
$ErrorActionPreference = "Stop"
Set-Location "$PSScriptRoot"

$python = Join-Path $PSScriptRoot "backend\venv\Scripts\python.exe"
if (!(Test-Path $python)) {
    Write-Host "Virtual environment not found. Run .\setup_public_environment.cmd first." -ForegroundColor Red
    exit 1
}

& (Join-Path $PSScriptRoot "run_public_environment.ps1") -Production @args
exit $LASTEXITCODE
